-- Capture observations supplement immutable missing-body conflicts; they never adopt content.
CREATE TABLE missing_body_capture_scopes(id TEXT PRIMARY KEY NOT NULL, snapshot_hash TEXT NOT NULL, processor_id TEXT NOT NULL REFERENCES identity_processors(id), format_version TEXT NOT NULL, manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)), members_hash TEXT NOT NULL);
CREATE TABLE missing_body_capture_scope_members(scope_id TEXT NOT NULL REFERENCES missing_body_capture_scopes(id), path TEXT NOT NULL, position TEXT NOT NULL, source_record_id TEXT NOT NULL REFERENCES source_records(id), input_hash TEXT NOT NULL, PRIMARY KEY(scope_id,path,position));
CREATE INDEX missing_body_capture_member_source ON missing_body_capture_scope_members(source_record_id);
CREATE TABLE missing_body_capture_observations(id TEXT PRIMARY KEY NOT NULL, conflict_id TEXT NOT NULL REFERENCES consolidation_conflicts(id), source_record_id TEXT NOT NULL REFERENCES source_records(id), capture_source_record_id TEXT NOT NULL REFERENCES source_records(id), path TEXT NOT NULL, position TEXT NOT NULL, input_hash TEXT NOT NULL, body_hash TEXT NOT NULL, body_length INTEGER NOT NULL CHECK(body_length>=0), stored_body_hash TEXT, stored_body_length INTEGER, source_status TEXT, matches_saved_hash INTEGER NOT NULL CHECK(matches_saved_hash IN (0,1)), UNIQUE(conflict_id,capture_source_record_id));
CREATE TABLE missing_body_capture_sets(id TEXT PRIMARY KEY NOT NULL, conflict_id TEXT NOT NULL REFERENCES consolidation_conflicts(id), source_record_id TEXT NOT NULL REFERENCES source_records(id), scope_id TEXT NOT NULL REFERENCES missing_body_capture_scopes(id), kind TEXT NOT NULL CHECK(kind IN ('initial','observation')), UNIQUE(conflict_id,scope_id));
CREATE TABLE missing_body_capture_set_members(set_id TEXT NOT NULL REFERENCES missing_body_capture_sets(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), observation_id TEXT NOT NULL REFERENCES missing_body_capture_observations(id), PRIMARY KEY(set_id,ordinal), UNIQUE(set_id,observation_id));
CREATE TRIGGER immutable_missing_body_capture_scopes_update BEFORE UPDATE ON missing_body_capture_scopes BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER immutable_missing_body_capture_scopes_delete BEFORE DELETE ON missing_body_capture_scopes BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER immutable_missing_body_capture_scope_members_update BEFORE UPDATE ON missing_body_capture_scope_members BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER immutable_missing_body_capture_scope_members_delete BEFORE DELETE ON missing_body_capture_scope_members BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER immutable_missing_body_capture_observations_update BEFORE UPDATE ON missing_body_capture_observations BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER immutable_missing_body_capture_observations_delete BEFORE DELETE ON missing_body_capture_observations BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER immutable_missing_body_capture_sets_update BEFORE UPDATE ON missing_body_capture_sets BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER immutable_missing_body_capture_sets_delete BEFORE DELETE ON missing_body_capture_sets BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER immutable_missing_body_capture_set_members_update BEFORE UPDATE ON missing_body_capture_set_members BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER immutable_missing_body_capture_set_members_delete BEFORE DELETE ON missing_body_capture_set_members BEGIN SELECT RAISE(ABORT,'immutable missing body capture history'); END;
CREATE TRIGGER missing_body_capture_source_update BEFORE UPDATE ON source_records WHEN EXISTS(SELECT 1 FROM missing_body_capture_scope_members WHERE source_record_id=OLD.id) OR EXISTS(SELECT 1 FROM missing_body_capture_sets WHERE source_record_id=OLD.id) BEGIN SELECT RAISE(ABORT,'immutable missing body source'); END;
CREATE TRIGGER missing_body_capture_parent_update BEFORE UPDATE ON consolidation_conflicts WHEN EXISTS(SELECT 1 FROM missing_body_capture_sets WHERE conflict_id=OLD.id) BEGIN SELECT RAISE(ABORT,'immutable missing body parent'); END;
CREATE TRIGGER missing_body_capture_source_delete BEFORE DELETE ON source_records WHEN EXISTS(SELECT 1 FROM missing_body_capture_scope_members WHERE source_record_id=OLD.id) OR EXISTS(SELECT 1 FROM missing_body_capture_sets WHERE source_record_id=OLD.id) BEGIN SELECT RAISE(ABORT,'immutable missing body source'); END;
CREATE TRIGGER missing_body_capture_parent_delete BEFORE DELETE ON consolidation_conflicts WHEN EXISTS(SELECT 1 FROM missing_body_capture_sets WHERE conflict_id=OLD.id) BEGIN SELECT RAISE(ABORT,'immutable missing body parent'); END;
